DomainResolver resolver = request -> {
    String host = request.getServerName();
    if (host.endsWith(".us.example.com")) return "tenant-us.auth0.com";
    return "tenant-eu.auth0.com";
};
AuthenticationController controller = AuthenticationController
    .newBuilder(resolver, "YOUR_CLIENT_ID", "YOUR_CLIENT_SECRET")
    .build();

try {
    Tokens tokens = controller.handle(request, response);
} catch (IdentityVerificationException e) {
    if (e.isAPIError()) {
        // Auth0 API returned an error response
    } else if (e.isJWTError()) {
        // Token signature or claims validation failed
    }
}

